    q.push(1);
    q.push(2);
    q.push(3);
    q.push(4);
    q.push(5);

    deleteAndReverse(q);

    // Output the remaining elements in the queue
    while (!q.empty()) {
        cout << q.front() << " ";
        q.pop();
    }

