CREATE PROCEDURE delete_employee(IN dssn varchar(64))
BEGIN
    DECLARE empDesignation varchar(128);
    DECLARE empSsn         varchar(64);
    DECLARE empMssn        varchar(64);

    SELECT SSN, designation, MSSN INTO empSsn, empDesignation, empMssn 
    FROM Employee 
    WHERE SSN = dssn;

    IF (empSsn IS NOT NULL) THEN
        CASE       
            WHEN empDesignation = 'OWNER' THEN 
                -- Signal an error because the owner cannot be deleted
                CALL my_signal('Error: OWNER cannot be deleted!');

            WHEN empDesignation = 'WORKER' THEN 
                -- Delete the worker from the table
                DELETE FROM Employee WHERE SSN = empSsn;               

            WHEN empDesignation = 'BOSS' THEN 
                BEGIN 
                    -- Update the MSSN of the employees under the deleted boss
                    UPDATE Employee
                    SET MSSN = empMssn
                    WHERE MSSN = empSsn;

                    -- Delete the boss from the table
                    DELETE FROM Employee WHERE SSN = empSsn;                   
                END;
        END CASE;
    ELSE 
        -- Signal an error because the row is not valid
