代码实现：
```
public int minWeight(int[] nums, int k) {
    int l = 1;
    int r = nums.length;
    while (l < r) {
        int mid = l + (r - l) / 2;
        if (check(nums, mid, k)) {
            r = mid;
        } else {
            l = mid + 1;
        }
    }
    return l;
}
private boolean check(int[] nums, int cnt, int k) {
    int[] parts = new int[cnt];
    for (int i = 0; i < nums.length; i++) {
        int pos = -1;
        for (int j = 0; j < cnt; j++) {
            if (pos == -1 || parts[pos] > parts[j]) {
                pos = j;
            }
        }
        parts[pos] += nums[i];
    }
    int max = 0;
    for (int i = 0; i < cnt; i++) {
        max = Math.max(max, parts[i]);
    }
    return max <= k;
}
```
