def midi_converter(note_names):
    note_values = {"C": 0, "D": 2, "E": 4, "F": 5, "G": 7, "A": 9, "B": 11}
    midi_numbers = []

    for note in note_names:
        note_letter = note[0].upper()
        accidental = note[1:2] if len(note) > 2 else ""
        octave = int(note[-1])

        base_midi = (octave + 1) * 12 + note_values[note_letter]

