def process(num):
    from math import gcd
    from functools import reduce

    def get_divisors(n):
        divisors = set()
        end = int(n ** 0.5)

        for i in range(1, end+1):
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)
        return list(divisors)

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    def lcm(a, b):
        return a * b // gcd(a, b)

    def get_highest_prime(divisors):
        primes = [i for i in divisors if is_prime(i)]
        return max(primes) if primes else 'No primes found'

    def get_gcd_lcm(divisors):
        if len(divisors) < 2:
            return 'Cannot compute GCD or LCM for less than 2 numbers'
        else:
            return (reduce(gcd, divisors), reduce(lcm, divisors))

    if not isinstance(num, (int, float)) or num < 0:
        return "Invalid Input"

    if num == 0:
        return 0, [], 0, 'No primes found', 'Cannot compute GCD or LCM for less than 2 numbers'

    num = int(num)
    divisors = get_divisors(num)
    return len(divisors) % 2 == 0, divisors, sum(divisors), get_highest_prime(divisors), get_gcd_lcm(divisors)


