                { name: 'Apple', imgSrc: 'apple.jpg' },
                { name: 'Kiwi', imgSrc: 'kiwi.jpg' },
                { name: 'Mango', imgSrc: 'mango.jpg' },
                { name: 'Banana', imgSrc: 'banana.jpg' },
                { name: 'Orange', imgSrc: 'orange.jpg' },
